using System;using System.Linq;using Hifc.Reference;
internal static class FloorAreaExportTests {
static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
static FieldCheck Field(string owner,string set,string name,string value)=>new FieldCheck{OwnerUniqueId=owner,PropertySet=set,Property=name,Source=name=="投影面积"?"建筑区域投影面积":name,Binding="实例",RawType="Real",State=value==null?"未填写":"有效",Value=value,Editable=true};
static ModelElementCheck Level(string value)=>new ModelElementCheck{Id=311,UniqueId="F1",Name="1F",Entity="IfcBuildingStorey",LevelUniqueId="F1",Fields=new[]{Field("F1",FloorAreaPolicy.FloorSet,"楼层面积",value)}};
static ModelElementCheck Region(int id,string value,string coefficient="1")=>new ModelElementCheck{Id=id,UniqueId=id.ToString(),Name="区域"+id,Entity="IfcSlab",Slot="建筑区域",LevelUniqueId="F1",ProjectedAreaM2=100,Fields=new[]{Field(id.ToString(),FloorAreaPolicy.RegionSet,"投影面积",value),Field(id.ToString(),FloorAreaPolicy.RegionSet,"计算系数",coefficient)}};
static FloorAreaPlan Plan(ModelElementCheck[] rows,PlanningSettings settings=null){var type=typeof(FloorAreaPolicy).Assembly.GetType("Hifc.Reference.FloorAreaExportPolicy");Assert(type!=null,"Export-specific advisory area policy is missing");return (FloorAreaPlan)type.GetMethod("Build").Invoke(null,new object[]{rows,settings??new PlanningSettings{RuleProfileId=PlatformRules.ProfileId,LevelsConfirmed=true,BuildingLevelUniqueIds=new[]{"F1"}}});}
static FloorAreaPlan Preserved(ModelElementCheck[] rows){var values=rows.SelectMany(r=>r.Fields.Select(f=>f.Value)).ToArray();var slots=rows.Select(r=>r.Slot).ToArray();var p=Plan(rows);Assert(p.Issues.Length==0&&p.Allocations.Length==0,"Export blocked or redistributed area");Assert(p.Notices.All(n=>!n.BlocksExport),"Area notice blocks export");Assert(values.SequenceEqual(rows.SelectMany(r=>r.Fields.Select(f=>f.Value)))&&slots.SequenceEqual(rows.Select(r=>r.Slot)),"Source values or classification changed");return p;}
public static void Run(Action<string,Action> check){
 check("export_area_over_five_percent_is_advisory_and_keeps_unclassified_excluded",()=>{var pending=Region(3,"500");pending.Slot=null;pending.Candidates=new[]{new ClassificationCandidate{Slot="建筑区域",RequiresReview=true}};var p=Preserved(new[]{Level("150"),Region(2,"100"),pending});Assert(p.Notices.Any(n=>n.Code=="FLOOR_AREA_DIFFERENCE"&&n.Detail.Contains("150")&&n.Detail.Contains("100")),"Written totals are not shown");Assert(p.Notices.Any(n=>n.Code=="FLOOR_AREA_UNCLASSIFIED"),"Unclassified scope notice missing");});
 check("export_area_overlap_is_visible_but_does_not_block",()=>{var a=Region(2,"60");var b=Region(3,"40");a.AreaAggregationIssue=b.AreaAggregationIssue="建筑区域投影重叠：2 / 3";var p=Preserved(new[]{Level("100"),a,b});Assert(p.Notices.Any(n=>n.Code=="FLOOR_AREA_SCOPE_REVIEW"&&n.Detail.Contains("2 / 3")),"Overlap was hidden");});
 check("export_fractional_corridor_keeps_projection_and_coefficient",()=>{var p=Preserved(new[]{Level("223.86"),Region(408657,"209.339"),Region(408666,"29.042","0.5")});Assert(p.Notices.Any(n=>n.Detail.Contains("238.381")),"Raw projection is not identified separately from billable area");});
 check("export_footprint_preserves_zero_coefficient_balcony",()=>{Preserved(new[]{Level("234.98"),Region(408648,"213.37"),Region(400469,"24.998","0")});});
 check("export_area_missing_value_does_not_use_geometry_or_zero",()=>{var a=Region(2,null);a.ProjectedAreaM2=999;var p=Preserved(new[]{Level("100"),a});Assert(a.Fields[0].Value==null&&p.Notices.Any(n=>n.Code=="FLOOR_AREA_VALUES_INCOMPLETE"),"Missing area filled or not reported");});
 check("export_area_metric_units_are_used_for_notices_only",()=>{var l=Level("1291.669");l.Fields[0].MetricValue=120;var a=Region(2,"1076.391");a.Fields[0].MetricValue=100;var p=Preserved(new[]{l,a});Assert(p.Notices.Any(n=>n.Detail.Contains("120")&&n.Detail.Contains("100")&&!n.Detail.Contains("1076.391")),"Internal square feet leaked into notice");});
 check("export_area_matching_values_need_no_difference_notice",()=>{var p=Preserved(new[]{Level("100"),Region(2,"100")});Assert(!p.Notices.Any(n=>n.Code=="FLOOR_AREA_DIFFERENCE"),"Matching areas generate false differences");});
 check("export_area_stale_level_selection_is_advisory",()=>{var p=Plan(new[]{Level("100"),Region(2,"100")},new PlanningSettings{LevelsConfirmed=true,BuildingLevelUniqueIds=new[]{"missing"}});Assert(p.Issues.Length==0&&p.Allocations.Length==0&&p.Notices.Any(n=>n.Code=="FLOOR_AREA_LEVEL_SCOPE"&&!n.BlocksExport),"Stale level selection not reported safely");});
}
}
